"variable "aws_region" {
  description = "AWS Region to deploy Mission Control (Bangkok)"
  type        = string
  default     = "ap-southeast-7"
}

variable "project_name" {
  description = "Project name prefix for tags and resources"
  type        = string
  default     = "mission-control"
}

variable "instance_type" {
  description = "EC2 Instance Type (Free Tier eligible / low-cost)"
  type        = string
  default     = "t3.micro"
}

variable "ebs_volume_size" {
  description = "Root EBS storage size in GB (Free Tier eligible up to 30GB)"
  type        = number
  default     = 20
}
"

"terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# 1. Data Sources for Network & AMI in Bangkok (ap-southeast-7)
data "aws_vpc" "default" {
  default = true
}

data "aws_subnets" "default" {
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.default.id]
  }
}

data "aws_ami" "ubuntu" {
  most_recent = true
  owners      = ["099720109477"] # Canonical

  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd-gp3/ubuntu-noble-24.04-amd64-server-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

# 2. SSH Key Pair Generation
resource "tls_private_key" "ssh" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "generated" {
  key_name   = "${var.project_name}-bkk-key"
  public_key = tls_private_key.ssh.public_key_openssh
}

resource "local_file" "private_key" {
  content         = tls_private_key.ssh.private_key_pem
  filename        = "${path.module}/mission_control_bkk_key.pem"
  file_permission = "0400"
}

# 3. Security Group for Web and SSH
resource "aws_security_group" "web" {
  name        = "${var.project_name}-bkk-sg"
  description = "Security Group for Mission Control Streamlit & Nginx (Bangkok)"
  vpc_id      = data.aws_vpc.default.id

  # HTTP
  ingress {
    description = "HTTP Public Access"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # HTTPS
  ingress {
    description = "HTTPS Public Access"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # Direct Streamlit 
